INSERT INTO `Pages` (`PageID`, `PageName`, `PageContent`) VALUES
(1,	'index',	'<p><big>&nbsp;&nbsp;&nbsp; I am an experienced DevOps/Cloud Engineer with a proven track record of driving business success through the strategic organization, execution, and delivery of key technical projects. My expertise in cloud architecture and infrastructure management, coupled with my ability to prioritize and implement high-impact solutions, makes me an ideal candidate for the DevOps/Cloud Engineer role at your organization.</big></p>\r\n\r\n<p><big>&nbsp;&nbsp;&nbsp; In my previous roles, I developed a precise and data-driven approach to problem-solving. I pride myself on my ability to work autonomously while embracing collaborative teamwork. My core competencies include cloud-based IT solution development, platform evaluation, and project management. I am particularly passionate about optimizing high-traffic SaaS applications, and I am confident that my strong technical and strategic planning skills will contribute to the continued growth and success of your organization.</big></p>\r\n\r\n<p><big>&nbsp;&nbsp;&nbsp; Early in my career, I became captivated by the transformative power of technology. As a Cloud Engineer, I have led numerous projects where I successfully implemented scalable, cloud-based solutions that yielded significant cost savings, improved system reliability, and enhanced client outcomes.</big></p>\r\n\r\n<p><big>&nbsp;&nbsp;&nbsp; In my current role at Cegid, I spearheaded a complete infrastructure migration to the cloud, resulting in substantial reductions in operational costs and improvements in system resilience and scalability. My work included using Infrastructure as Code (IAC) principles to migrate physical servers to Azure, leveraging tools such as Kubernetes (AKS), Terraform, Ansible, and Puppet. I also played a key role in migrating servers from OVH Cloud to Azure, ensuring a smooth transition with minimal disruption to business operations. My deep understanding of cloud architecture, combined with my analytical and problem-solving abilities, has allowed me to deliver measurable and impactful results.</big></p>\r\n\r\n<p><big>&nbsp;&nbsp;&nbsp; What truly differentiates me as a Cloud Engineer is my ability to communicate complex technical ideas to both technical and non-technical audiences. I believe that successful cloud solutions depend on fostering strong relationships and securing buy-in from all levels of an organization. My ability to bridge the gap between technical teams and business stakeholders has consistently led to successful project outcomes. I am confident that my technical expertise, strategic mindset, and communication skills will allow me to contribute effectively to your cloud initiatives.</big></p>\r\n\r\n<p><big>&nbsp;&nbsp;&nbsp; For further details on my career experience and achievements, please refer to my CV available at</big></p>\r\n'),
(2,	'whoami',	'As a mathematician with 15 years as a php programmer throughout the years, I now see myself as a software engineer and cloud engineer with particular interest in IAC.\r\n<br/><br/>\r\n<center>\r\nFavorite Sites<br/>\r\n<div class=\"toppostcategory\">\r\n<a href=\"https://thescottishgypsies.co.uk/\">The Gypsies of Scotland</a>\r\n</div>\r\n<div class=\"toppostcategory\">\r\n<a href=\"https://scottishborders.uk/\">Things to do in the Scottish Borders</a>\r\n</div>\r\n</center>');

