  `PostPublished` int(11) NOT NULL,
  `PostTitle` varchar(128) NOT NULL,
  `PostSummary` text NOT NULL,
  `PostContent` text NOT NULL,
  `PostImage` varchar(128) DEFAULT NULL,
  `PostThumbnail` varchar(128) DEFAULT NULL,
